var NUM = 35;
var SZE = 20; // will be calculated on screen dimensions later
var grid;

function setup() {
	createCanvas(windowWidth, windowHeight);
	describe("iso cube city: ground, rievrs, parks and buildings");
	displayDensity(1);
	frameRate(60);

	// dimesnions
	SZE_X = ~~ ( (width/Math.sqrt(3)) / (NUM+1))
	SZE_Y = ~~ ( (height/ (NUM+1)))
	SZE = min(SZE_X, SZE_Y)

	// array of iso cubes
	grid = []
	const clrBuildings = [color("rgb(104,14,14)"), color("rgb(138,93,11)"), color("rgb(139,139,156)"), color("rgb(15,15,152)")];

	// higher values can overwrite existing blocks
	const TYP_BASE = 1, TYP_PARK = 3, TYP_WATER = 4, TYP_BUILDING = 2;

	// base
	item = new IsoCube(0, 0, SZE, NUM, NUM, color("rgb(56,53,53)"), 0, TYP_BASE);
	// grid.push(item);
	for (yy = 0; yy < NUM; yy++) {					
		for (xx = 0; xx < NUM; xx++) {
			var clr = lerpColor(color(48), color(16), random());
			item = new IsoCube(xx, yy, SZE, 1, 1, clr, SZE/4, TYP_BASE);
			if (!isInGrid(item, grid)) grid.push(item);
		}
	}

	// parks
	for (i = 0; i <= NUM/5; i++) {
		for (tries = 0; tries < 10; tries++) {			
			var x = ~~random(1, NUM - 2), 
						y = ~~random(1, NUM - 2), 
						w = constrain(~~random(5, 9), 0, NUM-x-1), 
						h = constrain(~~random(5, 9), 0, NUM-y-1);
			item = new IsoCube(x, y, SZE, w, h, color("rgb(10,90,22)"), SZE/2, TYP_PARK);
			// if park is not overlapping 
			if (!isInGrid(item, grid)) {
				for (yy = y; yy < y + h; yy++) {					
					for (xx = x; xx < x + w; xx++) {
						var clr = lerpColor(color("rgb(26,176,26)"), color("rgb(7,69,7)"), random());
						item = new IsoCube(xx, yy, SZE, 1, 1, clr, SZE/2, TYP_PARK);
						grid.push(item);
					}
				}
				break;
			}
		}
	}

	// water
	{
		var x, y, w, h;
		// 1st river
		w = ~~random(1, 3.5), x = ~~random(1, NUM-w-1), y = 0, h = NUM;
		// item = new IsoCube(~~random(1, NUM-2), 0, SZE, 2, NUM, color("rgb(28,180,196)"), 4, TYP_WATER);
		// grid.push(item);
		for (yy = y; yy < y + h; yy++) {					
			for (xx = x; xx < x + w; xx++) {
				var clr = lerpColor(color("rgb(89,183,174)"), color("rgb(31,29,151)"), random());
				item = new IsoCube(xx, yy, SZE, 1, 1, clr, SZE/2, TYP_WATER);
				grid.push(item);
			}
		}
		// 2nd river		
		x = 0, w = NUM, h = ~~random(1, 3.5), y = ~~random(1, NUM-h-1);
		// item = new IsoCube(0, ~~random(1, NUM-2), SZE, NUM, 2, color("rgb(20,123,166)"), 4, TYP_WATER);
		for (yy = y; yy < y + h; yy++) {					
			for (xx = x; xx < x + w; xx++) {
				var clr = lerpColor(color("rgb(89,183,174)"), color("rgb(31,29,151)"), random());
				item = new IsoCube(xx, yy, SZE, 1, 1, clr, 4, TYP_WATER);
				grid.push(item);
			}
		}
	}

	// buildings
	for (i = 0; i < NUM * NUM / 10; i++) {
		for (tries = 0; tries < 100; tries++) {	
			let w = ~~random(1, 3.3), h =~~random(1, 3.4), x = ~~random(0, NUM-w), y = ~~random(0, NUM-h);
			// item.l = max(SZE, Math.pow(Math.pow(item.s, noise(width + item.x, height + item.y, frameCount * 0.0025) + 0.45), 1.25));
			const len = random()*random()*15*SZE;
			item = new IsoCube(x, y, SZE, w, h, random(clrBuildings), len, TYP_BUILDING);
			if (!isInGrid(item, grid)) {
				grid.push(item);
				break;
			}
		}
	}

	// base
	for (yy = 0; yy < NUM; yy++) {					
		for (xx = 0; xx < NUM; xx++) {
			var clr = lerpColor(color(48), color(16), random());
			item = new IsoCube(xx, yy, SZE, 1, 1, clr, 0, TYP_BASE);
			// if (!isInGrid(item, grid)) grid.push(item);
		}
	}

	// grid sort
	grid = grid.sort((a, b) => (a.x*a.y+a.x+a.y+a.w+a.h) - (b.x*b.y+b.x+b.y+b.w+b.h));
}



function draw() {
	background(100);

	// gradient
	const ctx = drawingContext;
	const gradient = ctx.createLinearGradient(0, 0, 0, height);
	gradient.addColorStop(0, color("navy"));
	gradient.addColorStop(1, color("silver"));
	ctx.fillStyle = gradient;
	ctx.fillRect(0, 0, width, height);	

	// cubes
	push()
	translate(width * 0.5, height * 0.5 - NUM * SZE * 0.5)
	for (item of grid) {
		// item.l = item.s + sin((frameCount * 0.02+ item.x + item.y) ) * item.s * 0.5;
		// item.l = Math.pow(item.s, noise(width + item.x, height + item.y, frameCount * 0.005) + 0.65); // map(noise(item.x, item.y, frameCount * 0.005), 0, 1, 0, item.s * 3)
		/* if (item.l > 0) */ // item.l = max(SZE, Math.pow(Math.pow(item.s, noise(width + item.x, height + item.y, frameCount * 0.0025) + 0.45), 1.25));
		n = (noise(width + item.x * 0.123, height + item.y * 0.321, frameCount * 0.0025) + 0.25);
		f = max(0, pow(n, 2.25)); // 75 * max(0, pow(n, 1.25)) * ( dist(item.x, item.y, 0, 0)) / max(width, height);
		// if (frameCount === 1) console.log("*", n, f)
		item.show(f);
	}
	pop()

	// // noLoop() removed for animation
}


