// checks, if rect is inside another rect and consideres type
function isInGrid(r1, arr) {
	for (r2 of arr) {
		if (!(r2.x >= r1.x + r1.w ||
    r2.x + r2.w <= r1.x ||
    r2.y >= r1.y + r1.h ||
    r2.y + r2.h <= r1.y)) {
			if (r1.typ <= r2.typ) return true;			
		}
	}

	return false;
}
